-- Retain former trial history; do not rewrite paid receipts, invoices or paid contracts.
CREATE TABLE retired_trial_memberships(owner_id TEXT PRIMARY KEY,terms_json TEXT,trial_started_at TEXT,trial_expires_at TEXT,retired_at TEXT NOT NULL);
INSERT INTO retired_trial_memberships SELECT owner_id,terms_json,trial_started_at,trial_expires_at,strftime('%Y-%m-%dT%H:%M:%fZ','now') FROM sandbox_memberships WHERE plan_id='free-30';
UPDATE sandbox_memberships SET plan_id='personal',terms_json='{"id":"personal","name":"Individual","audience":"Uso pessoal","meticais":0,"annualMeticais":0,"links":8,"bio":200,"description":"Os seus contactos e redes sociais, num só lugar.","active":true,"version":0,"entitlementVersion":1,"monthlyEnabled":false,"annualEnabled":false,"features":{"analytics":false,"whatsapp":false,"location":false,"showcase":false,"enquiries":false,"english":false,"team":false,"domain":false}}',version=version+1,updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE plan_id='free-30';
INSERT OR IGNORE INTO sandbox_memberships(owner_id,plan_id,version,updated_at,terms_json) SELECT id,'personal',1,strftime('%Y-%m-%dT%H:%M:%fZ','now'),'{"id":"personal","name":"Individual","audience":"Uso pessoal","meticais":0,"annualMeticais":0,"links":8,"bio":200,"description":"Os seus contactos e redes sociais, num só lugar.","active":true,"version":0,"entitlementVersion":1,"monthlyEnabled":false,"annualEnabled":false,"features":{"analytics":false,"whatsapp":false,"location":false,"showcase":false,"enquiries":false,"english":false,"team":false,"domain":false}}' FROM auth_accounts WHERE active=1 AND role IN ('customer','agent');
UPDATE manager_records SET data_json=json_set(data_json,'$.meticais',0,'$.annualMeticais',0,'$.active',json('true'),'$.monthlyEnabled',json('false'),'$.annualEnabled',json('false')),version=version+1 WHERE kind='plan' AND id='personal';
UPDATE manager_records SET data_json=json_set(data_json,'$.active',json('false')),version=version+1 WHERE kind='plan' AND id='free-30';
UPDATE profile_billing_settings SET enabled=1,opened_at=COALESCE(opened_at,strftime('%Y-%m-%dT%H:%M:%fZ','now')),version=version+1 WHERE id=1 AND enabled=0;
INSERT INTO manager_audit VALUES('permanent-individual-20261018','system','Plano Individual permanente','Experiência de 30 dias retirada. Contratos pagos e conteúdo privado preservados.',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
